def predecessor(root,before):
 folder=root/prior.FOLDER;base=read(folder/'BASELINE.json');require(pin(folder/'metadata-before.zip')==base['archive'],'Earlier MatrixEQTL archive changed')
 with zipfile.ZipFile(folder/'metadata-before.zip')as archive:
  require(set(archive.namelist())==set(META),'Earlier archive population changed');older={n:archive.read(n)for n in META}
 require({n:identity(raw)for n,raw in older.items()}==base['metadata'],'Earlier archived bytes changed');registry=prior.predecessor(root,older);expected,registry,_=prior.transition(older,registry,read(root/prior.ROLES)['roles']);require(expected==before and read(folder/'REGISTRY.json')==registry,'Predecessor differs from exact retained MatrixEQTL transition');return registry

def transition(before,registry,roles):
 papers,inventory,summary,ledger=[json.loads(before[META[i]])for i in [0,1,2,7]];require((len(papers),len(inventory),sum(len(p['tools'])for p in papers),len(ledger['reviews']),len(registry))==(250,453,2734,1844,492),'Predecessor totals changed');require({r['paper_id']for r in roles}=={'P023','P115','P118','P240'}and len(roles)==4,'All four flashpca source roles required');coverage=[]
